  gate(st.isDirectory()&&!st.isSymbolicLink()&&st.uid===process.getuid()&&(st.mode&0o777)===0o700,'EVIDENCE_ROOT_BOUNDARY');
  const ignore=path.join(full,'.gitignore'),ig=fs.lstatSync(ignore);
